function extractMessages(resp) {
  const p = resp.payload;
  if (Array.isArray(p)) return p;
  if (p && Array.isArray(p.payload)) return p.payload;
  return [];
}

const body           = $input.item.json.body;
const conversationId = body?.conversation?.id;
const myMsgId        = String(body?.id || '');
const myMsgIdInt     = parseInt(myMsgId) || 0;

let isLatest = true;

try {
  const resp = await this.helpers.httpRequest({
    method : 'GET',
    url    : 'https://chat.maxxitele.com.br/api/v1/accounts/1/conversations/' + conversationId + '/messages',
    headers: { 'api_access_token': 'b2E9nG1XtDJYrJaZg9j984mQ' },
    json   : true
  });

  const messages = extractMessages(resp)
    .sort((a, b) => (b.id || 0) - (a.id || 0)); // mais recente primeiro

  // CHECK 1 - Buffer: nossa msg deve ser a mais recente do cliente
  const latestIncoming = messages.find(m => m.message_type == 0);
  if (latestIncoming && String(latestIncoming.id) !== myMsgId) {
    isLatest = false; // chegou msg mais nova, outra execucao responde
  }

  // CHECK 2 - Seguran�a: bot j� respondeu DEPOIS da nossa msg?
  if (isLatest) {
    const botAfterUs = messages.find(m => m.message_type == 1 && (m.id || 0) > myMsgIdInt);
    if (botAfterUs) {
      isLatest = false; // resposta j� foi enviada, ignorar
    }
  }

} catch(e) {
  // Se API falhar, deixa passar (n�o bloquear o fluxo)
  isLatest = true;
}

return [{ json: { ...$input.item.json, isLatest } }];

