function extractMessages(resp) {
  const p = resp.payload;
  if (Array.isArray(p)) return p;
  if (p && Array.isArray(p.payload)) return p.payload;
  return [];
}
function descreverMsg(m) {
  if (m.content && m.content.trim()) return m.content.trim();
  const att = m.attachments && m.attachments[0];
  if (att) {
    if (att.file_type === 'image') return '[Imagem enviada]';
    if (att.file_type === 'audio') return '[Audio enviado]';
    return '[Arquivo: ' + att.file_type + ']';
  }
  return null;
}

const GEM_KEY = 'YOUR_GOOGLE_API_KEY';
const CW_TK   = 'b2E9nG1XtDJYrJaZg9j984mQ';
const CW_URL  = 'https://chat.maxxitele.com.br/api/v1/accounts/1';

const prevData       = $input.first().json;
const mediaContent   = prevData.mediaContent || null;
const wb             = $('Webhook Chatwoot').first().json.body;
const sender         = wb.conversation?.meta?.sender || {};
const conversationId = wb.conversation.id;
const contactId      = sender.id || wb.contact_inbox?.contact_id;
const nome           = sender.name || 'Cliente';
const telefone       = sender.phone_number || '';
const ultimaMensagem = wb.content || '';

// Historico completo (obrigatorio em todas as respostas)
let todasMsgs = [];
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: CW_URL + '/conversations/' + conversationId + '/messages',
    headers: { 'api_access_token': CW_TK },
    json: true
  });
  todasMsgs = extractMessages(resp).sort((a, b) => (a.id || 0) - (b.id || 0));
} catch(e) {}

const msgLines = todasMsgs.map(m => {
  const role = m.message_type == 0 ? 'Cliente' : 'Atendente';
  const txt  = descreverMsg(m);
  if (!txt) return null;
  const ts = m.created_at
    ? new Date(m.created_at * 1000).toLocaleTimeString('pt-BR', { hour:'2-digit', minute:'2-digit' })
    : '';
  return (ts ? '[' + ts + '] ' : '') + role + ': ' + txt;
}).filter(Boolean);

// Divide em chunks de 20 msgs — chamada Gemini Flash por chunk
const CHUNK_SIZE = 20;
const chunks = [];
for (let i = 0; i < msgLines.length; i += CHUNK_SIZE) {
  chunks.push(msgLines.slice(i, i + CHUNK_SIZE));
}
if (chunks.length === 0) {
  const msgAtual = mediaContent?.type === 'audio'
    ? '[Audio] ' + (mediaContent.transcription || '')
    : mediaContent?.type === 'image'
    ? '[Imagem] ' + (mediaContent.analysis || '')
    : (ultimaMensagem || 'mensagem sem texto');
  chunks.push(['Cliente: ' + msgAtual]);
}

// Chamada individual ao Gemini Flash por cada chunk
const chunkSummaries = [];
for (let i = 0; i < chunks.length; i++) {
  const chunk = chunks[i];
  const total = chunks.length;
  const label = total === 1 ? 'TRECHO UNICO'
    : i === 0 ? 'TRECHO INICIAL'
    : i === total - 1 ? 'TRECHO MAIS RECENTE' : 'TRECHO INTERMEDIARIO';
  const prompt = 'Analise este ' + label + ' do historico de atendimento C6 Bank:\n\n'
    + chunk.join('\n')
    + '\n\nResponda em topicos:\n- STATUS DA CONTA: (nao iniciou/em analise/aprovada/reprovada)\n- PASSO A PASSO: (enviado? cliente confirmou? reacao?)\n- PRINTS ENVIADOS: (conta em analise? conta aberta? nenhum?)\n- COMPROMISSOS: (prometeu responder quando?)\n- OBJECOES: (resistencias do cliente)\n- INFO CLIENTE: (tipo empresa, MEI?, ja tem C6 PF?, nome empresa)';
  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=' + GEM_KEY,
      headers: { 'Content-Type': 'application/json' },
      body: { contents: [{ parts: [{ text: prompt }] }] },
      json: true
    });
    const text = resp?.candidates?.[0]?.content?.parts?.[0]?.text;
    if (text) chunkSummaries.push('[Analise ' + (i+1) + '/' + total + ']\n' + text.trim());
  } catch(e) {
    chunkSummaries.push('[Analise ' + (i+1) + '/' + total + ']: Erro - ' + e.message);
  }
}

// Conversas anteriores
let convAnteriores = '';
if (contactId) {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: CW_URL + '/contacts/' + contactId + '/conversations',
      headers: { 'api_access_token': CW_TK },
      json: true
    });
    const outras = (resp.payload || [])
      .filter(c => String(c.id) !== String(conversationId))
      .slice(0, 3);
    if (outras.length > 0) {
      convAnteriores = outras.map(c => {
        const labels = (c.labels || []).join(', ') || 'sem etiquetas';
        const data   = new Date((c.created_at || 0) * 1000).toLocaleDateString('pt-BR');
        return 'Conv #' + c.id + ' (' + data + ') | ' + labels + ' | ' + (c.status || '');
      }).join('\n');
    }
  } catch(e) {}
}

return [{
  json: {
    conversationId,
    contactId,
    contactName:    nome,
    contactPhone:   telefone,
    ultimaMensagem,
    mediaContent,
    totalMensagens: msgLines.length,
    chunks:         chunks.length,
    chunkSummaries,
    convAnteriores
  }
}];

const dados   = $input.first().json;
const GEM_KEY = 'YOUR_GOOGLE_API_KEY';

let query = dados.ultimaMensagem || '';
if (dados.mediaContent?.type === 'audio') query = dados.mediaContent.transcription || query;
else if (dados.mediaContent?.type === 'image') query = '[Imagem] ' + (dados.mediaContent.analysis || query);

const KB = `CONTA PJ C6 BANK:
