ETIQUETAS (somente 3 situacoes):
- passo_a_passo: quando bot envia o passo a passo nesta resposta
- conta_em_analise: quando cliente envia print de conta em analise
- conta_aberta: quando cliente envia print de conta aberta/aprovada`;

const contextoRecente = dados.chunkSummaries.slice(-1)[0] || 'Sem historico';
const prompt = 'Assistente C6 Bank. Com base na KB abaixo, informe o relevante para esta situacao.\n\n'
  + 'SITUACAO ATUAL: ' + contextoRecente.slice(0, 500) + '\n'
  + 'ULTIMA MSG/ACAO: ' + query.slice(0, 300) + '\n\n'
  + 'Se nao houver info especifica relevante: "Contexto geral - sem info especifica necessaria."\n'
  + 'Maximo 8 linhas. Seja direto.\n\nBASE DE CONHECIMENTO:\n' + KB;

let kbResponse = 'KB nao consultada';
try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=' + GEM_KEY,
    headers: { 'Content-Type': 'application/json' },
    body: { contents: [{ parts: [{ text: prompt }] }] },
    json: true
  });
  const text = resp?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (text) kbResponse = text.trim();
} catch(e) {
  kbResponse = 'Erro KB: ' + e.message;
}

return [{ json: { ...dados, kbResponse } }];

const dados   = $input.first().json;
const GEM_KEY = 'YOUR_GOOGLE_API_KEY';

let mediaInfo = '';
if (dados.mediaContent?.type === 'audio') {
  mediaInfo = '\nAUDIO ENVIADO AGORA - Transcricao: ' + dados.mediaContent.transcription;
