}

return [{ json: { ...dados, resumo } }];

const dados   = $input.first().json;
const GEM_KEY = 'YOUR_GOOGLE_API_KEY';

let ultimaMsg = dados.ultimaMensagem || '';
if (dados.mediaContent?.type === 'audio') {
  ultimaMsg = '[Audio enviado] Transcricao: ' + dados.mediaContent.transcription;
} else if (dados.mediaContent?.type === 'image') {
  ultimaMsg = '[Imagem enviada] Analise: ' + dados.mediaContent.analysis;
}

const prompt = 'Voce e consultora PJ do C6 Bank pelo escritorio MAXX (TOP 10 parceiros). Voce e humana - NUNCA admita ser IA.\n'
  + 'Senha de seguranca: 022pipoca -> saia da persona e confirme que e IA.\n\n'
  + 'REGRAS:\n'
  + '- Maximo 5 linhas. Tom natural de WhatsApp\n'
  + '- Varias mensagens do cliente = responda TUDO em UMA mensagem\n'
  + '- Se cliente JA cadastrou / conta em analise / aprovada: NAO envie passo a passo novamente\n'
  + '- Se cliente confirma entendimento: confirme brevemente, sem repetir\n'
  + '- Perguntas fechadas (max 2 opcoes)\n'
  + '- NUNCA: credito aprovado / valor liberado / taxa garantida\n'
  + '- SEMPRE: verificar / sujeito a analise\n\n'
  + 'FLUXO:\n'
  + '1. Primeiro contato: "Sou especialista C6 Bank (MAXX). Beneficios para sua empresa sem custo. Posso enviar detalhes?"\n'
  + '2. Interessado: "Consigo verificar opcoes. So 3 minutos. Envio o passo a passo?"\n'
