  + 'Escreva APENAS o texto da mensagem para o WhatsApp. Sem aspas, sem "Resposta:", sem explicacoes. Maximo 5 linhas.';

let resposta = 'Ola! Estou verificando sua situacao. Pode me contar mais sobre sua empresa?';
try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-pro:generateContent?key=' + GEM_KEY,
    headers: { 'Content-Type': 'application/json' },
    body: { contents: [{ parts: [{ text: prompt }] }] },
    json: true
  });
  const text = resp?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (text) resposta = text.trim();
} catch(e) {}

return [{ json: { ...dados, respostaFinal: resposta } }];

// Aplica etiqueta SOMENTE nas 3 situacoes permitidas:
// 1. Bot enviou passo a passo NESTA resposta
// 2. Cliente enviou print de conta EM ANALISE
// 3. Cliente enviou print de conta ABERTA/APROVADA

const dados         = $input.first().json;
const resposta      = (dados.respostaFinal || '').toLowerCase();
const mediaAnalysis = (dados.mediaContent?.analysis || '').toLowerCase();
const CW_TK         = 'b2E9nG1XtDJYrJaZg9j984mQ';
const CW_URL        = 'https://chat.maxxitele.com.br/api/v1/accounts/1';
const conversationId = dados.conversationId;

let etiqueta = null;

// SITUACAO 1: Bot enviou passo a passo NESTA resposta
const padPP = [
  'play.google.com/store/apps/details',
  'apps.apple.com/br/app/c6-bank',
  'conta empresarial (nao mei)',
  'conta empresarial (não mei)',
  'abrir conta > conta empresarial',
  '1. baixe o app c6',
  '1.baixe o app c6',
  'baixe o app c6 bank',
  'bonequinho > c6 empresas'
];
if (padPP.some(p => resposta.includes(p))) {
  etiqueta = 'passo_a_passo';
}

// SITUACAO 2: Cliente enviou print de conta EM ANALISE (na analise da imagem)
if (!etiqueta && dados.mediaContent?.type === 'image') {
  const padAnalise = [
    'em análise', 'em analise', 'analisando', 'aguardando aprovação',
    'aguardando aprovacao', 'sendo analisada', 'conta em análise',
    'conta em analise', 'under review', 'aguardando analise'
  ];
  if (padAnalise.some(p => mediaAnalysis.includes(p))) {
    etiqueta = 'conta_em_análise';
  }
}

// SITUACAO 3: Cliente enviou print de conta ABERTA/APROVADA (na analise da imagem)
if (!etiqueta && dados.mediaContent?.type === 'image') {
  const padAberta = [
    'conta aberta', 'conta aprovada', 'aprovada com sucesso',
    'bem-vindo ao c6', 'conta criada', 'cadastro aprovado',
    'conta ativa', 'sua conta foi aprovada', 'conta pj aberta',
    'abertura concluída', 'cadastro concluído'
  ];
  if (padAberta.some(p => mediaAnalysis.includes(p))) {
    etiqueta = 'conta_aberta';
  }
}

// Aplica etiqueta preservando as nao-status existentes
if (etiqueta && conversationId) {
  try {
    const currentResp = await this.helpers.httpRequest({
      method: 'GET',
      url: CW_URL + '/conversations/' + conversationId + '/labels',
      headers: { 'api_access_token': CW_TK },
      json: true
    });
    const currentLabels  = currentResp?.payload || [];
    const statusLabels   = ['passo_a_passo', 'conta_em_análise', 'conta_aberta'];
    const novasEtiquetas = [
      ...currentLabels.filter(l => !statusLabels.includes(l)),
      etiqueta
    ];
    await this.helpers.httpRequest({
      method: 'POST',
      url: CW_URL + '/conversations/' + conversationId + '/labels',
      headers: { 'Content-Type': 'application/json', 'api_access_token': CW_TK },
      body: { labels: novasEtiquetas },
      json: true
    });
  } catch(e) {}
}

return [{ json: { ...dados, etiquetaAplicada: etiqueta } }];
